mapper.select:
SELECT * FROM products p
JOIN subcategories s ON p.subcategory_id = s.subcategory_id
WHERE s.category_id = #{categoryId}

mapper.update:
	UPDATE products
	SET p_name=#{p_name}, p_color=#{p_color}, p_width=#{p_width}, p_price=#{p_price},
    	p_image=#{p_image}, p_rating=#{p_rating}, subcategory_id=#{subcategoryId}, category_id=#{categoryId}, external_url=#{externalUrl}
	WHERE p_code=#{p_code}
